paramConversion.applyStepsToNormalizedParameterValue:
function applyStepsToNormalizedParameterValue(normalizedValue, steps) {
    if (steps == 1) {
        if (normalizedValue > 0) {
            normalizedValue = 1.;
        }
    } else {
        let oneStep = 1. / (steps - 1);
        let numberOfSteps = rnbo_fround(normalizedValue / oneStep * 1 / 1) * 1;
        normalizedValue = numberOfSteps * oneStep;
    }

    return normalizedValue;
}

paramConversion.convertToNormalizedParameterValue:
function convertToNormalizedParameterValue(index, value) {
    switch (index) {
    case 2:
        {
            value = (value < -24 ? -24 : (value > 0 ? 0 : value));
            let normalizedValue = (value - -24) / (0 - -24);
            return normalizedValue;
        }
    case 0:
        {
            value = (value < -24 ? -24 : (value > 24 ? 24 : value));
            let normalizedValue = (value - -24) / (24 - -24);
            return normalizedValue;
        }
    case 1:
        {
            value = (value < 0.1 ? 0.1 : (value > 10 ? 10 : value));
            let normalizedValue = (value - 0.1) / (10 - 0.1);
            return normalizedValue;
        }
    case 4:
        {
            value = (value < 0.1 ? 0.1 : (value > 3000 ? 3000 : value));
            let normalizedValue = (value - 0.1) / (3000 - 0.1);
            return normalizedValue;
        }
    case 3:
        {
            value = (value < 0.01 ? 0.01 : (value > 30 ? 30 : value));
            let normalizedValue = (value - 0.01) / (30 - 0.01);
            return normalizedValue;
        }
    default:
        return value;
    }
}

paramConversion.convertFromNormalizedParameterValue:
function convertFromNormalizedParameterValue(index, value) {
    value = (value < 0 ? 0 : (value > 1 ? 1 : value));

    switch (index) {
    case 2:
        {
            {
                return -24 + value * (0 - -24);
            }
        }
    case 0:
        {
            {
                return -24 + value * (24 - -24);
            }
        }
    case 1:
        {
            {
                return 0.1 + value * (10 - 0.1);
            }
        }
    case 4:
        {
            {
                return 0.1 + value * (3000 - 0.1);
            }
        }
    case 3:
        {
            {
                return 0.01 + value * (30 - 0.01);
            }
        }
    default:
        return value;
    }
}

paramConversion.constrainParameterValue:
function constrainParameterValue(index, value) {
    var v = value;

    switch (index) {
    case 0:
        {
            v = (v > 24 ? 24 : (v < -24 ? -24 : v));
            return v;
        }
    case 1:
        {
            v = (v > 10 ? 10 : (v < 0.1 ? 0.1 : v));
            return v;
        }
    case 2:
        {
            v = (v > 0 ? 0 : (v < -24 ? -24 : v));
            return v;
        }
    case 3:
        {
            v = (v > 30 ? 30 : (v < 0.01 ? 0.01 : v));
            return v;
        }
    case 4:
        {
            v = (v > 3000 ? 3000 : (v < 0.1 ? 0.1 : v));
            return v;
        }
    default:
        return value;
    }
}
